function renderCalendarAgenda(key){var items=(window.portalAgenda||[]).filter(function(r){return dayKey(dateValue(r))===key});$('#calendar-dialog .calendar-agenda').innerHTML='<span class="eyebrow">'+escapeHtml(formatDate(key,false).toUpperCase())+'</span>'+(items.length?items.map(function(r){return '<button data-detail-id="'+r.id+'"><b>'+escapeHtml(timeValue(r))+' · '+escapeHtml(rowTitle(r))+'</b><small>'+escapeHtml(r.location||r.description||'Agenda internal')+'</small></button>'}).join(''):'<div><b>Tidak ada agenda</b><small>Pilih tanggal lain atau tambah agenda baru.</small></div>')}
$('#open-calendar').onclick=function(){calendarMonth=new Date();renderCalendar();$('#calendar-dialog').showModal()};$('#calendar-dialog .calendar-toolbar button:first-child').onclick=function(){calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()-1,1);renderCalendar()};$('#calendar-dialog .calendar-toolbar button:last-child').onclick=function(){calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+1,1);renderCalendar()};$('#calendar-dialog').onclick=function(e){var date=e.target.closest('[data-calendar-date]');if(date)renderCalendarAgenda(date.dataset.calendarDate)};
function visibleManagerRows(){var q=($('#manager-search').value||'').toLowerCase(),filterDate=$('#manager-date').value,sort=$('#manager-sort').value,rows=managerRows.filter(function(r){return JSON.stringify(r).toLowerCase().indexOf(q)>-1&&(!filterDate||dateOnly(dateValue(r))===filterDate)});rows.sort(function(a,b){if(sort==='title')return rowTitle(a).localeCompare(rowTitle(b),'id');var diff=String(dateValue(b)).localeCompare(String(dateValue(a)));return sort==='oldest'?-diff:diff});return rows}
function renderManager(){var rows=visibleManagerRows();$('#manager-count').textContent=rows.length+' data';$('#manager-list').innerHTML=rows.length?rows.map(function(r){var m=managerMeta(r);return '<article class="manager-row" data-detail-id="'+r.id+'"><div class="manager-row-icon">'+escapeHtml((rowTitle(r)[0]||'D').toUpperCase())+'</div><div><b>'+escapeHtml(rowTitle(r))+'</b><small>'+escapeHtml(m.filter(Boolean).join(' · '))+'</small></div><div class="manager-row-actions"><button data-edit="'+r.id+'">Edit</button><button class="danger" data-delete="'+r.id+'">Hapus</button></div></article>'}).join(''):'<div class="empty"><b>Belum ada data</b><span>Tekan “Tambah data” untuk membuat catatan pertama.</span></div>'}
