/* Avatar paths are persisted in the signed-in user's auth metadata, so the feature works without a database migration. */
(function(){
  var profileWithAvatar=applyProfile;
  applyProfile=function(profile,user){
    var authAvatar=user&&user.user_metadata&&user.user_metadata.avatar_url;
    profileWithAvatar(Object.assign({},profile,{avatar_url:(profile&&profile.avatar_url)||authAvatar||''}),user);
  };
})();


