/* One consistent work-data form replaces separate manager formats. */
(function(){
  var originalLoadManager=loadManager,allRows=[];
  function formatUnifiedDate(row){return row.start_at||row.agenda_date||row.start_date||row.status_date||row.created_at||''}
  function loadUnified(){var list=$('#manager-list');if(!list)return;list.innerHTML='<div class="empty"><b>Memuat data…</b></div>';Promise.all([safeRows('agendas'),safeRows('perjalanan_dinas'),safeRows('status_tim'),safeRows('informasi')]).then(function(groups){allRows=[];groups[0].forEach(function(row){allRows.push({_table:'agendas',_type:'Agenda',title:rowTitle(row),date:formatUnifiedDate(row),row:row})});groups[1].forEach(function(row){allRows.push({_table:'perjalanan_dinas',_type:'Perjalanan dinas',title:row.destination||row.tujuan||rowTitle(row),date:formatUnifiedDate(row),row:row})});groups[2].forEach(function(row){allRows.push({_table:'status_tim',_type:'Status tim',title:(row.status||'Status tim').replace(/^./,function(c){return c.toUpperCase()}),date:formatUnifiedDate(row),row:row})});groups[3].forEach(function(row){allRows.push({_table:'informasi',_type:'Informasi',title:rowTitle(row),date:formatUnifiedDate(row),row:row})});allRows.sort(function(a,b){return String(b.date).localeCompare(String(a.date))});$('#manager-count').textContent=allRows.length+' data';list.innerHTML=allRows.length?allRows.slice(0,20).map(function(item){return '<article class="manager-row unified-row"><span class="unified-type">'+escapeHtml(item._type)+'</span><div><b>'+escapeHtml(item.title)+'</b><small>'+escapeHtml(rowDate(item.row)||'Belum ada tanggal')+'</small></div></article>'}).join(''):'<div class="empty"><b>Belum ada data</b><span>Gunakan tombol Tambah data untuk mencatat data pertama.</span></div>'})}
  function openUnifiedForm(){managerTable='data_terpadu';$('#manager-id').value='';$('#manager-dialog-title').textContent='Tambah data';$('#manager-fields').innerHTML='<label class="record-label">Jenis data<select name="jenis" required><option value="agenda">Agenda</option><option value="perjalanan">Perjalanan dinas</option><option value="status">Status tim</option><option value="informasi">Informasi</option></select></label><label class="record-label">Judul atau kegiatan<input name="title" required></label><label class="record-label">Tanggal<input name="tanggal" type="date" required></label><label class="record-label">Waktu<input name="waktu" type="time" value="08:00"></label><label class="record-label">Lokasi atau unit terkait<input name="lokasi"></label><label class="record-label">Keterangan<textarea name="keterangan" rows="3"></textarea></label>';$('#manager-error').textContent='';$('#manager-dialog').showModal()}
  loadManager=function(){if(managerTable==='data_terpadu')return loadUnified();return originalLoadManager()};
  document.querySelectorAll('#manager-tabs button').forEach(function(button){button.style.display='none'});$('#manager-add').textContent='+ Tambah data';managerTable='data_terpadu';
  $('#manager-add').onclick=openUnifiedForm;
  $('#manager-form').onsubmit=async function(event){event.preventDefault();var form=new FormData(event.target),data=Object.fromEntries(form.entries()),save=$('#manager-save');if(managerTable!=='data_terpadu')return;save.disabled=true;save.textContent='Menyimpan…';$('#manager-error').textContent='';try{if(data.jenis==='agenda')await apiWrite('agendas','POST',null,{title:data.title,start_at:data.tanggal+'T'+data.waktu,end_at:'',location:data.lokasi,description:data.keterangan,visibility:'tim'});if(data.jenis==='perjalanan')await apiWrite('perjalanan_dinas','POST',null,{tujuan:data.title,tanggal_mulai:data.tanggal,tanggal_selesai:data.tanggal,kegiatan:data.keterangan,anggota:data.lokasi,status:'rencana'});if(data.jenis==='status')await apiWrite('status_tim','POST',null,{status:'rapat',tanggal:data.tanggal,keterangan:data.title+(data.keterangan?' — '+data.keterangan:'')});if(data.jenis==='informasi')await apiWrite('informasi','POST',null,{title:data.title,ringkasan:data.keterangan,user_id:currentSession().user.id});$('#manager-dialog').close();showToast('Data berhasil disimpan.');loadUnified();syncPortalData(currentSession().user)}catch(error){$('#manager-error').textContent=error.message}finally{save.disabled=false;save.textContent='Simpan'}};
  var avatar=$('.profile-avatar'),edit=$('#edit-profile-button');if(avatar&&edit&&!avatar.querySelector('#edit-profile-button')){edit.className='avatar-edit';edit.textContent='Edit';avatar.appendChild(edit)};
})();

/* Reliable profile editor shortcut: avoid routing through a moved hidden button. */
(function(){
  function openProfileEditor(){
    var profile=window.currentProfile||{};
    var full=$('#profile-full-name-input'),nickname=$('#profile-nickname-input'),unit=$('#profile-unit-input'),form=$('#profile-form');
    if(!full||!nickname||!unit||!form)return;
    full.value=profile.full_name||'';
    nickname.value=profile.nickname||'';
    unit.value=profile.unit||'Bidang Mineral dan Batubara';
    var previous=$('#profile-photo-field');if(previous)previous.remove();
    var field=document.createElement('label');
    field.className='record-label upload-field profile-photo-field';
    field.id='profile-photo-field';
    field.innerHTML='Foto profil<input id="profile-photo-input" type="file" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG, atau WEBP. Maksimal 2 MB.</small><span id="profile-photo-name">'+escapeHtml(profile.avatar_url?'Foto profil tersimpan':'Belum ada foto dipilih')+'</span>';
    form.insertBefore(field,form.querySelector('.dialog-actions'));
    var photo=$('#profile-photo-input');
    if(photo)photo.onchange=function(){var name=$('#profile-photo-name');if(name)name.textContent=this.files[0]?this.files[0].name:'Belum ada foto dipilih'};
    var error=$('#profile-form-error');if(error)error.textContent='';
    var dialog=$('#profile-dialog');if(dialog)dialog.showModal();
  }
  window.openProfileEditor=openProfileEditor;
  var edit=$('#edit-profile-button');if(edit)edit.onclick=openProfileEditor;
  var settings=$('.profile-settings');
  if(settings)settings.addEventListener('click',function(event){
    var button=event.target.closest('[data-profile-action="edit"]');
    if(!button)return;
    event.preventDefault();event.stopImmediatePropagation();
    openProfileEditor();
  },true);
})();
